271.     {
272.         ArgumentException.ThrowIfNullOrWhiteSpace(culture);
273.         ArgumentNullException.ThrowIfNull(formatter);
274.         lock (_writeLock)
275.         {
276.             var builder = new Dictionary<string, IFormatter>(_formatters, StringComparer.OrdinalIgnoreCase)
277.             {
