321. /// Strategies for humanizing date/time differences.
322. /// </summary>
323. public sealed class DefaultDateTimeHumanizeStrategy
324. {
325.     /// <summary>
326.     /// Humanizes a DateTime difference relative to a base date.
327.     /// </summary>
328.     /// <param name="input">The date to humanize.</param>
329.     /// <param name="comparedTo">The reference date (typically DateTime.UtcNow).</param>
330.     /// <returns>A human-readable string representing the time difference.</returns>
331.     public string Humanize(DateTime input, DateTime comparedTo)
332.     {
333.         var difference = comparedTo - input;
334.         if (Math.Abs(difference.TotalSeconds) < 2)
335.         {
336.             return "just now";
337.         }
338. 
339.         var isFuture = difference.TotalSeconds < 0;
340.         var absDiff = difference.Duration();
341. 
342.         var result = absDiff.TotalDays switch
343.         {
344.             >= 365 => $"{(int)(absDiff.TotalDays / 365)} years",
345.             >= 31 => $"{(int)(absDiff.TotalDays / 30)} months",
346.             >= 1 => $"{(int)absDiff.TotalDays} days",
347.             _ => absDiff.TotalHours switch
348.             {
349.                 >= 1 => $"{(int)absDiff.TotalHours} hours",
350.                 _ => absDiff.TotalMinutes switch
351.                 {
352.                     >= 1 => $"{(int)absDiff.TotalMinutes} minutes",
353.                     _ => $"{(int)absDiff.TotalSeconds} seconds"
354.                 }
355.             }
356.         };
357. 
358.         return isFuture ? $"in {result}" : $"{result} ago";
359.     }
360. }
