     }

     private static string GetUnitName(TimeUnit timeUnit, int count)
     {
         // Avoid enum.ToString().ToLowerInvariant() — two allocations per call.
         // Return cached string literals instead.
         return (timeUnit, count) switch
         {
             (TimeUnit.Year, 1) => "year",
             (TimeUnit.Year, _) => "years",
             (TimeUnit.Month, 1) => "month",
             (TimeUnit.Month, _) => "months",
             (TimeUnit.Day, 1) => "day",
             (TimeUnit.Day, _) => "days",
             (TimeUnit.Hour, 1) => "hour",
             (TimeUnit.Hour, _) => "hours",
             (TimeUnit.Minute, 1) => "minute",
             (TimeUnit.Minute, _) => "minutes",
             (TimeUnit.Second, 1) => "second",
             (TimeUnit.Second, _) => "seconds",
             _ => count == 1
                 ? timeUnit.ToString().ToLowerInvariant()
                 : timeUnit.ToString().ToLowerInvariant() + "s"
         };
     }

     private static string NumberToWords(int number) =>
         number switch
         {
             1 => "one",
             2 => "two",
             3 => "three",
             _ => number.ToString()
